//! action.rs — DATA TWIN of skills/engine/canonical-actions/action.mjs, generated by the crossing's expand.mjs.
//! NAMES ARE CONTRACT: statics carry the exact JS export names. The value is the JS
//! value, pressed at expansion time and proven by the conform 'const' lane (ε0 full-value
//! equality). Drift watch re-opens the unit if the JS source changes.
// QUALITY: 78/100 — generated data twin: proven byte-fidelity (ε0 full-value), embedded blob unreadable by design
use serde_json::Value;
use std::sync::LazyLock;

pub static ACTIONS: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(r#"[{"name":"system.action.add","description":"Add a new action (audited).","owner_agent":"system","steps_json":"[{\"skill\":\"with-audit\",\"input\":{\"skill\":\"action-add\",\"wrappedInput\":\"$.input\",\"operation\":\"action.add\",\"entity_type\":\"action\",\"entity_id\":\"$.input.name\"},\"as\":\"action\"}]","returns":"$.results.action","on_failure":"rollback"},{"name":"system.action.run","description":"Run a action by name.","owner_agent":"system","steps_json":"[{\"skill\":\"action-run\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.action.verify","description":"Run an action's verification_json spec: seed pre-state, check preconditions, dispatch the action, then assert postconditions + audit-row landings. Returns {passed, pre_checks, post_checks, audit_checks}. Input: {action_name, action_input?, seed_sql?[]}. Skips with reason when an action has no spec.","owner_agent":"system","steps_json":"[{\"skill\":\"action-verify\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.action.verify.coverage","description":"Report which actions have a verification_json spec filled vs not. Groups by owner_agent; flags high-leverage actions still uncovered. Pure read.","owner_agent":"system","steps_json":"[{\"skill\":\"action-verify-coverage\",\"input\":\"$.input\",\"as\":\"report\"}]","returns":"$.results.report","on_failure":"abort"},{"name":"system.action.find","description":"Semantic search over action descriptions. Input: {query, limit?, minScore?}. Falls back to substring search if no embeddings stored.","owner_agent":"system","steps_json":"[{\"skill\":\"catalog-find\",\"input\":{\"query\":\"$.input.query\",\"entity_type\":\"action\",\"limit\":\"$.input.limit\",\"minScore\":\"$.input.minScore\"},\"as\":\"matches\"}]","returns":"$.results.matches","on_failure":"abort"},{"name":"system.action.list","description":"Filter-based listing of actions (complement to system.action.find). Supports {kind: atomic|workflow, owner_agent, limit}. Returns deterministic name-sorted list. Card #377.","owner_agent":"system","steps_json":"[{\"skill\":\"action-list\",\"input\":\"$.input\",\"as\":\"matches\"}]","returns":"$.results.matches","on_failure":"abort"}]"#).expect("ACTIONS: embedded JSON is valid by construction")
});

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::Value;

    #[test]
    fn actions_parses_with_the_pressed_shape() {
        let v: &Value = &ACTIONS;
        let a = v.as_array().expect("array");
        assert_eq!(a.len(), 6, "pressed length");
        let mut names: Vec<&str> = a.iter().map(|x| x["name"].as_str().expect("name")).collect();
        let n = names.len();
        names.sort(); names.dedup();
        assert_eq!(names.len(), n, "names unique");
    }

}
